  4096 <= p -> p + c <= hl_ceil L -> PM.tb_ok s tg ->
  hi_heap HI ((p, c) :: LB) cr0 M (m_vmmaps model) -> model_but_vm model0 model ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x5911c M model) K.
